(()=>{'use strict';if(window.__communityRatingsStarted)return;window.__communityRatingsStarted=true;
if(!document.querySelector('link[href^="rating-summary.css"]')){const css=document.createElement('link');css.rel='stylesheet';css.href='rating-summary.css?v=20261027brand';document.head.append(css)}
const NS='http://www.w3.org/2000/svg',path='m12 2.5 2.94 5.96 6.58.96-4.76 4.64 1.12 6.55L12 17.52l-5.88 3.09 1.12-6.55L2.48 9.42l6.58-.96Z';let ratings=[],state='loading',uid=0;
function stars(area,value){area.replaceChildren();for(let i=0;i<5;i++){const svg=document.createElementNS(NS,'svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('aria-hidden','true');const base=document.createElementNS(NS,'path');base.setAttribute('d',path);base.setAttribute('class','rating-star-empty');svg.append(base);const amount=Math.max(0,Math.min(1,value-i));if(amount){const clip=document.createElementNS(NS,'clipPath'),rect=document.createElementNS(NS,'rect'),id='community-star-'+(++uid);clip.id=id;rect.setAttribute('width',String(24*amount));rect.setAttribute('height','24');clip.append(rect);const defs=document.createElementNS(NS,'defs');defs.append(clip);const fill=document.createElementNS(NS,'path');fill.setAttribute('d',path);fill.setAttribute('clip-path',`url(#${id})`);fill.setAttribute('class','rating-star-filled');svg.append(defs,fill)}area.append(svg)}}
function render(badge){const target=badge.dataset.ratingSummary,row=ratings.find(r=>r.target===target),count=Math.max(0,Number(row?.count)||0),average=count?Math.max(0,Math.min(5,Number(row.average)||0)):0,name=target==='helper'?'Franklin helper':'GTA V iOS launcher';stars(badge.querySelector('.rating-stars'),average);badge.querySelector('.rating-summary-score').textContent=state==='ready'&&count?average.toFixed(1):'';const countNode=badge.querySelector('.rating-summary-count');if(countNode)countNode.textContent='';const status=state==='ready'?(count?average.toFixed(1)+' out of 5':'no ratings yet'):'ratings '+(state==='error'?'unavailable':'loading');badge.setAttribute('aria-label',`${name}: ${status}. Share your experience.`);badge.title=badge.getAttribute('aria-label')}
function mountLauncher(){const badge=document.querySelector('[data-rating-summary="launcher"]'),brand=document.querySelector('.site-header .site-brand'),header=brand?.parentElement;if(!badge||!brand||!header)return;if(badge.parentElement!==header)header.insertBefore(badge,brand.nextSibling);badge.classList.add('rating-summary-header')}
function mountHelper(){for(const title of document.querySelectorAll('.ask-franklin-title')){if(title.querySelector('[data-rating-summary="helper"]'))continue;const badge=document.createElement('a');badge.className='rating-summary rating-summary-helper';badge.dataset.ratingSummary='helper';badge.href='feedback.html';badge.innerHTML='<span class="rating-stars" aria-hidden="true"></span><span class="rating-summary-score"></span><span class="rating-summary-count" hidden></span>';title.append(badge);render(badge)}}
function renderAll(){mountLauncher();mountHelper();document.querySelectorAll('[data-rating-summary]').forEach(render)}
renderAll();const observer=new MutationObserver(()=>{mountLauncher();mountHelper()});observer.observe(document.body,{childList:true,subtree:true});
async function load(){try{const response=await fetch('/api/feedback',{cache:'no-store'});if(!response.ok)throw Error();const data=await response.json();if(!Array.isArray(data.ratings))throw Error();ratings=data.ratings;state='ready'}catch{state='error'}renderAll()}load();window.addEventListener('community-rating-updated',load);
})();
